/// The base with item code `code`.
#[must_use]
pub fn base(code: &str) -> Option<Base> {
    let i = BASES.binary_search_by(|row| row.0.cmp(code)).ok()?;
    let &(code, slot, kind, class, str, dex) = BASES.get(i)?;
    Some(Base {
        code,
        slot,
        kind,
        class,
        str,
        dex,
    })
}

